using MediStock.Data;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;
namespace MediStock.Pages.Invoices;[Authorize]public sealed class IndexModel(MediStockDbContext db):PageModel{[BindProperty(SupportsGet=true)]public string?Search{get;set;}public IReadOnlyList<InvoiceRow>Items{get;private set;}=[];public async Task OnGetAsync(CancellationToken ct){var q=db.Sales.AsNoTracking();if(!string.IsNullOrWhiteSpace(Search)){var s=Search.Trim();q=q.Where(x=>EF.Functions.Like(x.InvoiceNumber,$"%{s}%")||x.SoldAtUtc.ToString().Contains(s));}Items=await q.OrderByDescending(x=>x.SoldAtUtc).Select(x=>new InvoiceRow(x.Id,x.InvoiceNumber,x.SoldAtUtc,x.TotalAmount,x.PaymentMethod)).ToListAsync(ct);}}
public sealed record InvoiceRow(int Id,string InvoiceNumber,System.DateTime Date,decimal Total,string PaymentMethod);
